(()=>{
 const loading=document.getElementById('loading');let finished=false;
 function recovery(){if(finished||document.getElementById('startup-recovery'))return;const panel=document.createElement('div');panel.id='startup-recovery';panel.style.cssText='max-width:440px;padding:20px;text-align:center';const text=document.createElement('p');text.textContent='Não foi possível concluir a abertura. Atualize os arquivos do site e tente novamente; seu catálogo e rascunhos serão preservados.';const link=document.createElement('a');link.href='/offline-update.html?return=site';link.textContent='Atualizar e abrir o site';link.className='primary';link.style.cssText='display:inline-block;text-decoration:none;border-radius:8px';const offline=document.createElement('a');offline.href='/offline.html';offline.textContent='Abrir lista offline';offline.style.cssText='display:block;margin-top:16px;color:#86e7c6';panel.append(text,link,offline);loading.append(panel);const caption=loading.querySelector(':scope > p');if(caption)caption.textContent='A abertura está demorando mais que o esperado.';}
 const watchdog=setTimeout(recovery,35000);
 async function prepare(){if(!('serviceWorker' in navigator))return;try{const registration=await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});await registration.update();const worker=registration.installing||registration.waiting;if(worker&&worker.state!=='activated')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker.removeEventListener('statechange',check);reject(new Error('Atualização não concluída.'));},15000);function check(){if(worker.state==='activated'){clearTimeout(timer);worker.removeEventListener('statechange',check);resolve();}else if(worker.state==='redundant'){clearTimeout(timer);worker.removeEventListener('statechange',check);reject(new Error('Atualização interrompida.'));}}worker.addEventListener('statechange',check);check();});}catch(error){if(navigator.serviceWorker.controller)throw error;}}
 (async()=>{try{await prepare();const app=await import('/script.js');await app.appReady;finished=true;clearTimeout(watchdog);document.getElementById('startup-recovery')?.remove();}catch(error){console.error('Falha ao iniciar o site:',error);clearTimeout(watchdog);recovery();}})();
})();
